import threading, http.server, json, sys, urllib.error
sys.path.insert(0, '.')
from weather import WeatherClient
def serve(fail_n):
    state={'n':0}
    class H(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            state['n']+=1
            if state['n']<=fail_n:
                self.send_response(503); self.end_headers(); return
            self.send_response(200); self.end_headers(); self.wfile.write(b'{"ok":1}')
        def log_message(self,*a): pass
    s=http.server.HTTPServer(('127.0.0.1',0),H)
    threading.Thread(target=s.serve_forever,daemon=True).start()
    return s,state
s,st=serve(2)
print(WeatherClient(f"http://127.0.0.1:{s.server_port}",backoff=0.01).get("x"), st)
s2,st2=serve(99)
try: WeatherClient(f"http://127.0.0.1:{s2.server_port}",backoff=0.01).get("x")
except urllib.error.HTTPError as e: print("raised",e.code,st2)

